panels = []
DEBUG_RAISE = True  # TEMPORARY: True lets real errors surface via Quarto's own
                    # traceback reporting. Set False once things work, so one
                    # bad storm can't take down the whole page in production.

if has_storms:
    for storm in selected_storms:
        try:
            panels.append(process_storm(storm))
        except Exception:
            if DEBUG_RAISE:
                raise
            tb = traceback.format_exc().replace("--", "- -")
            label = storm.get("dropdown_label", storm.get("id"))
            print(f"&lt;!-- Skipped {label}:\n{tb}\n--&gt;")

if not panels:
    print("&lt;p&gt;&lt;strong&gt;No storms could be rendered right now.&lt;/strong&gt; "
          "Either there are no active storms in AL/EP/CP, or all of them "
          "failed (see HTML comments in the page source, or the terminal "
          "output, for why).&lt;/p&gt;")
else:
    html = ['&lt;div style="margin-bottom:1em;"&gt;',
            '&lt;label for="storm-select"&gt;&lt;strong&gt;Select a storm:&lt;/strong&gt;&lt;/label&gt; ',
            '&lt;select id="storm-select" onchange="showStormPanel(this.value)"&gt;']
    for i, p in enumerate(panels):
        sel = " selected" if i == 0 else ""
        html.append(f'&lt;option value="storm-{p["slug"]}"{sel}&gt;{p["label"]}&lt;/option&gt;')
    html.append("&lt;/select&gt;&lt;/div&gt;")

    for i, p in enumerate(panels):
        display = "block" if i == 0 else "none"
        # RUN_TOKEN cache-busts the image so your browser can't show a
        # stale copy of a file that has the same name across renders.
        html.append(
            f'&lt;div id="storm-{p["slug"]}" class="storm-panel" style="display:{display};"&gt;'
            f'&lt;img src="{p["img_path"]}?v={RUN_TOKEN}" style="max-width:100%;" /&gt;'
            f'&lt;/div&gt;'
        )

    html.append("""
&lt;script&gt;
function showStormPanel(id) {
  document.querySelectorAll('.storm-panel').forEach(function (el) {
    el.style.display = (el.id === id) ? 'block' : 'none';
  });
}
&lt;/script&gt;
""")
    print("\n".join(html))

